import React from 'react';
import { IconButton } from '@mui/material';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import { useLocation, useNavigate } from 'react-router-dom';
import { claimBackRequest } from '../utils/backNavigation';

// The universal back arrow (Round 32.6, Eddie 2026-11-18): one
// arrow, on every page, in one consistent place — a glass circle
// fixed at the top-left, directly under the top bar, mirroring
// the notification toasts' top-right perch (same offsets, same
// glass family as the battle D-pad / Stroll scene controls).
//
// Placement law, measured not assumed:
// - It is NOT in the Toolbar: the phone top bar fits a 390px
//   layout viewport exactly (Rounds 17/22 fit trims) and carries
//   no spare width — the arrow must never widen it. The top-bar
//   law is re-proven with the arrow mounted.
// - zIndex 1250: above page content, the bottom tab bar (1150)
//   and the fight screen's fixed overlay (1200) — a duel is
//   exited THROUGH this arrow, via the fight's own doors (see
//   utils/backNavigation.ts) — and below the MUI dialogs (1300)
//   and the toast stack (1310), which keep covering it.
// - Top-left under the bar clears every page's first content:
//   pages open with paper padding at that corner, the World
//   Map's own controls sit top-right / bottom-left INSIDE the
//   map (well below this perch), and Stroll's Swap overlay is
//   scene-relative (16px into a scene that starts far lower).
//
// Behaviour: true history back within the SPA — the last thing
// you were doing, across tabs included (the router's history
// index says whether an in-app previous screen exists). On a
// cold entry (deep link, index 0) there is no in-app previous
// screen, so the arrow falls back to the page's parent — every
// route in this app is one level deep, so the parent is Home.
const BackButton: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();

  const handleBack = () => {
    // A live fight claims the press and exits through its own
    // doors (forfeit / settle) — never a raw history pop.
    if (claimBackRequest()) return;
    const idx = (window.history.state as { idx?: number } | null)?.idx ?? 0;
    if (idx > 0) {
      navigate(-1);
      return;
    }
    // Cold entry: parent route (Home for every one-level route;
    // on Home itself the arrow simply stays home).
    if (location.pathname !== '/') navigate('/', { replace: true });
  };

  return (
    <IconButton
      data-testid="shell-back-button"
      aria-label="Go back"
      onClick={handleBack}
      sx={{
        position: 'fixed',
        top: { xs: 64, sm: 76 },
        left: 12,
        zIndex: 1250,
        width: 40,
        height: 40,
        color: '#eaf6fa',
        backgroundColor: 'rgba(13, 47, 63, 0.55)',
        backdropFilter: 'blur(10px)',
        WebkitBackdropFilter: 'blur(10px)',
        border: '1px solid rgba(120, 200, 225, 0.34)',
        boxShadow: '0 6px 18px rgba(0, 0, 0, 0.35)',
        '&:hover': {
          backgroundColor: 'rgba(13, 47, 63, 0.78)',
          borderColor: 'rgba(120, 200, 225, 0.65)',
        },
      }}
    >
      <ArrowBackIcon />
    </IconButton>
  );
};

export default BackButton;
