import React, { useEffect, useState } from 'react';
import { Box, Button, Chip, IconButton, Menu, MenuItem, Paper, Typography } from '@mui/material';
import {
  EMPTY_MODERATION,
  MODERATION_CHANGED_EVENT,
  canModerate,
  loadModeration,
  roleInSpace,
  saveModeration,
  type ModSystemLine,
  type SpaceModeration,
  type SpaceRole,
} from '../utils/moderation';

// Moderation UI (Round 35) — the shared pieces every people-chat
// space renders: role badges, the per-message action menu, the
// pinned area, the locked banner, the participants panel, and the
// system lines flag-and-notify posts into the space. The state
// itself lives in utils/moderation.ts (one record per space);
// these components only render it and call back.
//
// The controls are deliberately VISIBLE (a ⋯ button on a message,
// named buttons on a person's row) — moderation a player can't
// find doesn't exist, and Eddie's order was EASY controls inside
// the space itself, not gestures to discover.

// Testids can't carry the raw participant/message keys (they
// contain ':' and, on the forums, spaces) — sanitize for testids.
export function testKey(key: string): string {
  return key.replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

// Live view of one space's moderation record. Both doors of a
// group (Friends page + Inbox) hold this hook, so a change made
// through one door appears through the other without a reload.
export function useSpaceModeration(spaceId: string | null): {
  mod: SpaceModeration;
  map: Record<string, SpaceModeration>;
  update: (next: SpaceModeration) => void;
} {
  const [map, setMap] = useState<Record<string, SpaceModeration>>(() => loadModeration());
  useEffect(() => {
    const reload = () => setMap(loadModeration());
    window.addEventListener(MODERATION_CHANGED_EVENT, reload);
    window.addEventListener('storage', reload);
    return () => {
      window.removeEventListener(MODERATION_CHANGED_EVENT, reload);
      window.removeEventListener('storage', reload);
    };
  }, []);
  const mod = (spaceId ? map[spaceId] : undefined) ?? EMPTY_MODERATION;
  const update = (next: SpaceModeration) => {
    if (!spaceId) return;
    const fresh = loadModeration();
    fresh[spaceId] = next;
    saveModeration(fresh);
  };
  return { mod, map, update };
}

// The role badge — shown next to a person's name IN THIS SPACE
// ONLY. A moderator here is a plain member everywhere else.
export const ModBadge: React.FC<{ role: SpaceRole; testId?: string }> = ({ role, testId }) => {
  if (role === 'member') return null;
  return (
    <Chip
      size="small"
      color={role === 'owner' ? 'warning' : 'info'}
      label={role === 'owner' ? 'OWNER' : 'MOD'}
      data-testid={testId ?? `mod-badge-${role}`}
      sx={{ height: 18, fontWeight: 700, flexShrink: 0 }}
    />
  );
};

export const RoleBadgeFor: React.FC<{
  mod: SpaceModeration;
  ownerKey: string;
  participantKey: string;
}> = ({ mod, ownerKey, participantKey }) => (
  <ModBadge role={roleInSpace(mod, ownerKey, participantKey)} />
);

// One flag-and-notify line, rendered in the space's own flow.
export const SystemLineRow: React.FC<{ line: ModSystemLine }> = ({ line }) => (
  <Box sx={{ alignSelf: 'center', maxWidth: '92%' }} data-testid="mod-system-line">
    <Typography variant="caption" color="text.secondary" align="center" sx={{ display: 'block' }}>
      {line.text}
    </Typography>
  </Box>
);

// Merge a space's messages with its moderation system lines into
// one chronological flow. Stable sort: at equal timestamps the
// messages (listed first) precede the lines they caused.
export type FlowItem<M> =
  | { kind: 'msg'; ts: number; index: number; msg: M }
  | { kind: 'sys'; ts: number; line: ModSystemLine };

export function mergeFlow<M extends { ts: number }>(
  messages: M[],
  lines: ModSystemLine[]
): FlowItem<M>[] {
  const items: FlowItem<M>[] = [
    ...messages.map((msg, index) => ({ kind: 'msg' as const, ts: msg.ts, index, msg })),
    ...lines.map(line => ({ kind: 'sys' as const, ts: line.ts, line })),
  ];
  return items.sort((a, b) => a.ts - b.ts);
}

// The pinned spot for a space: pinned messages live here, above
// the flow, until unpinned or removed.
export const PinnedArea: React.FC<{
  items: { key: string; authorLabel: string; text: string }[];
  canMod: boolean;
  onUnpin: (key: string) => void;
}> = ({ items, canMod, onUnpin }) => {
  if (items.length === 0) return null;
  return (
    <Paper
      data-testid="mod-pinned-area"
      sx={{ p: 1.5, mb: 1.5, borderRadius: 2, bgcolor: 'rgba(255,179,0,0.10)' }}
    >
      <Typography variant="caption" color="text.secondary">
        📌 Pinned in this space
      </Typography>
      {items.map(item => (
        <Box
          key={item.key}
          data-testid={`mod-pinned-${testKey(item.key)}`}
          sx={{ display: 'flex', gap: 1, alignItems: 'flex-start', mt: 0.5 }}
        >
          <Typography variant="body2" sx={{ flexGrow: 1, minWidth: 0 }}>
            <strong>{item.authorLabel}:</strong> {item.text}
          </Typography>
          {canMod && (
            <Button
              size="small"
              data-testid={`mod-unpin-${testKey(item.key)}`}
              onClick={() => onUnpin(item.key)}
            >
              Unpin
            </Button>
          )}
        </Box>
      ))}
    </Paper>
  );
};

// The locked banner: a locked space says so, plainly, where the
// composer would be — and offers the unlock to those who hold it.
export const LockedBanner: React.FC<{
  noun: string;
  canMod: boolean;
  onUnlock: () => void;
}> = ({ noun, canMod, onUnlock }) => (
  <Paper
    data-testid="mod-locked-banner"
    sx={{ p: 2, mt: 1, borderRadius: 2, bgcolor: 'rgba(244,67,54,0.10)', textAlign: 'center' }}
  >
    <Typography variant="body2">🔒 This {noun} is locked — new posts are paused here.</Typography>
    {canMod && (
      <Button size="small" sx={{ mt: 1 }} data-testid="mod-unlock-btn" onClick={onUnlock}>
        Unlock {noun}
      </Button>
    )}
  </Paper>
);

// The per-message action menu (owner + moderators only — callers
// render it only for them). Pin/unpin and Remove live here.
export const MessageModMenu: React.FC<{
  messageKey: string;
  pinned: boolean;
  onPin: () => void;
  onUnpin: () => void;
  onRemove: () => void;
}> = ({ messageKey, pinned, onPin, onUnpin, onRemove }) => {
  const [anchor, setAnchor] = useState<HTMLElement | null>(null);
  const san = testKey(messageKey);
  const close = () => setAnchor(null);
  return (
    <>
      <IconButton
        size="small"
        aria-label="Moderation actions for this message"
        data-testid={`mod-menu-${san}`}
        onClick={e => setAnchor(e.currentTarget)}
        sx={{ p: 0.25, fontSize: '0.9rem', lineHeight: 1 }}
      >
        ⋯
      </IconButton>
      <Menu anchorEl={anchor} open={anchor !== null} onClose={close}>
        {pinned ? (
          <MenuItem
            data-testid={`mod-act-unpin-${san}`}
            onClick={() => {
              close();
              onUnpin();
            }}
          >
            📌 Unpin message
          </MenuItem>
        ) : (
          <MenuItem
            data-testid={`mod-act-pin-${san}`}
            onClick={() => {
              close();
              onPin();
            }}
          >
            📌 Pin message
          </MenuItem>
        )}
        <MenuItem
          data-testid={`mod-act-remove-${san}`}
          onClick={() => {
            close();
            onRemove();
          }}
        >
          🛡️ Remove message
        </MenuItem>
      </Menu>
    </>
  );
};

export interface ParticipantRowData {
  key: string;
  label: string;
}

// The people-in-this-space panel: the member list, the badges,
// and — for the owner and moderators — the appoint / mute /
// remove controls on each person's row. Removed participants are
// NOT passed in: they have left the space and its lists.
// Permission shape (Round 35 brief): the OWNER appoints and
// removes moderators and can act on anyone but themselves;
// MODERATORS can mute/remove plain members; nobody acts on the
// owner or on themselves.
export const ParticipantsPanel: React.FC<{
  mod: SpaceModeration;
  ownerKey: string;
  viewerKey: string;
  participants: ParticipantRowData[];
  onAppoint: (key: string, label: string) => void;
  onUnappoint: (key: string, label: string) => void;
  onMute: (key: string, label: string) => void;
  onUnmute: (key: string, label: string) => void;
  onRemove: (key: string, label: string) => void;
}> = ({
  mod,
  ownerKey,
  viewerKey,
  participants,
  onAppoint,
  onUnappoint,
  onMute,
  onUnmute,
  onRemove,
}) => {
  const viewerRole = roleInSpace(mod, ownerKey, viewerKey);
  return (
    <Paper sx={{ p: 2, mb: 2, borderRadius: 3 }} data-testid="mod-participants">
      <Typography variant="subtitle1" gutterBottom>
        People in this space
      </Typography>
      {participants.map(p => {
        const role = roleInSpace(mod, ownerKey, p.key);
        const muted = mod.mutedKeys.includes(p.key);
        const isSelf = p.key === viewerKey;
        const showControls = canModerate(viewerRole) && !isSelf && role !== 'owner';
        const canAppoint = viewerRole === 'owner' && showControls;
        const canActOn = showControls && (viewerRole === 'owner' || role === 'member');
        return (
          <Box
            key={p.key}
            data-testid={`mod-participant-${testKey(p.key)}`}
            sx={{
              display: 'flex',
              gap: 1,
              flexWrap: 'wrap',
              alignItems: 'center',
              py: 0.75,
              borderBottom: '1px solid rgba(255,255,255,0.06)',
            }}
          >
            <Typography variant="body2" sx={{ fontWeight: 600 }}>
              {p.label}
              {isSelf ? ' (you)' : ''}
            </Typography>
            <ModBadge role={role} />
            {muted && <Chip size="small" variant="outlined" label="Muted" sx={{ height: 18 }} />}
            {canAppoint &&
              (role === 'moderator' ? (
                <Button
                  size="small"
                  data-testid={`mod-unappoint-${testKey(p.key)}`}
                  onClick={() => onUnappoint(p.key, p.label)}
                >
                  Remove moderator
                </Button>
              ) : (
                <Button
                  size="small"
                  data-testid={`mod-appoint-${testKey(p.key)}`}
                  onClick={() => onAppoint(p.key, p.label)}
                >
                  Make moderator
                </Button>
              ))}
            {canActOn &&
              (muted ? (
                <Button
                  size="small"
                  data-testid={`mod-unmute-${testKey(p.key)}`}
                  onClick={() => onUnmute(p.key, p.label)}
                >
                  Unmute
                </Button>
              ) : (
                <Button
                  size="small"
                  data-testid={`mod-mute-${testKey(p.key)}`}
                  onClick={() => onMute(p.key, p.label)}
                >
                  Mute
                </Button>
              ))}
            {canActOn && (
              <Button
                size="small"
                color="error"
                data-testid={`mod-remove-participant-${testKey(p.key)}`}
                onClick={() => onRemove(p.key, p.label)}
              >
                Remove from space
              </Button>
            )}
          </Box>
        );
      })}
      <Typography variant="caption" color="text.secondary">
        Moderation here is built in: the owner can appoint moderators, and owners and moderators can
        pin, remove posts, mute or remove people, and lock the space — every action posts a small
        note in this space only. Demo moderation, on this device.
      </Typography>
    </Paper>
  );
};
