import React from 'react';
import ReactDOM from 'react-dom/client';
import './styles/global.css';
// Modern View design layer (integration build, 2026-11-16): tokens,
// glide-and-snap motion, stage + map privacy styles. Additive only.
import './styles/modern.css';
// Brand-rename migration (icewall-* -> glacer-* storage keys) must
// run BEFORE App — and therefore before every context that reads
// localStorage in a state initializer — is even imported.
import { migrateLegacyStorageKeys } from './utils/legacyStorage';
import { installChunkRecoveryNet } from './utils/chunkRecovery';
import { installVersionHeal } from './utils/versionHeal';
import ShellErrorBoundary from './components/ShellErrorBoundary';
import App from './App';

migrateLegacyStorageKeys();
// Round 31: chunk-load failures that surface outside a React render
// (window error / unhandled rejection from the webpack runtime) get
// the same one-reload self-recovery the error boundaries apply.
installChunkRecoveryNet();
// Hotfix round: if this shell is stale (the deployed build has
// moved on since the shell was cached), heal with one guarded
// reload at boot — the shell-level sibling of the chunk recovery.
installVersionHeal();

const root = ReactDOM.createRoot(document.getElementById('root') as HTMLElement);
root.render(
  <React.StrictMode>
    <ShellErrorBoundary>
      <App />
    </ShellErrorBoundary>
  </React.StrictMode>
);
