// Stroll compass + personal pins (Round 33.5, Eddie 2026-11-18
// ~15:30 PT: a compass on Stroll guiding to a chosen venue, a
// battle spot, a wild navitar, or the player's own pin —
// "navitar, remember where I parked my car").
//
// PRIVACY, absolute (the standing law, applied here):
//   - The compass points to PLACES, spawns and the player's own
//     pins — NEVER to people. There is no person target kind and
//     there never will be.
//   - Personal pins live ONLY in this device's localStorage. They
//     are never rendered on the shared map or heat, never sent
//     anywhere, and are visible to no venue, player or admin.
//   - The player's own position is read on-device (geolocation)
//     and held in a ref by the Stroll page — never stored, never
//     sent. A pin stores only the PIN's coordinates, on-device.
//
// The target is a single record so the venue panel on the World
// Map ("🧭 Guide me there") and the compass on Stroll always agree:
// RealmMap writes it, the compass reads it, and a window event
// keeps any mounted readers in step within the tab.

import { DEMO_VENUES, type DemoVenue } from '../data/venues';
import { buzzForVenue } from '../data/venueBuzz';

export interface GeoFix {
  lat: number;
  lng: number;
  // Device course over ground (degrees, compass convention) when
  // the fix carries one; null when stationary / unavailable.
  heading: number | null;
  speed: number | null;
  ts: number;
}

export interface PersonalPin {
  id: string;
  name: string;
  lat: number;
  lng: number;
  createdAt: number;
}

// 'wild' carries no coordinates on purpose: a wild spawn is a live
// scene event, resolved from the scene itself while it stands.
export type CompassTarget =
  | { kind: 'venue'; id: string; label: string; lat: number; lng: number }
  | { kind: 'battle'; id: string; label: string; lat: number; lng: number }
  | { kind: 'pin'; id: string; label: string; lat: number; lng: number }
  | { kind: 'wild'; label: string };

const PINS_KEY = 'glacer-personal-pins';
const TARGET_KEY = 'glacer-compass-target';
const CHOSEN_VENUE_KEY = 'glacer-compass-venue';
const CHANGED_EVENT = 'glacer-compass-changed';

function notifyCompassChanged(): void {
  try {
    window.dispatchEvent(new Event(CHANGED_EVENT));
  } catch {
    // No window (SSR/tests) — readers fall back to their own state.
  }
}

// Subscribe to any compass-store change (target, pins, chosen
// venue) made anywhere in this tab. Returns an unsubscribe.
export function subscribeCompassChanges(fn: () => void): () => void {
  window.addEventListener(CHANGED_EVENT, fn);
  window.addEventListener('storage', fn);
  return () => {
    window.removeEventListener(CHANGED_EVENT, fn);
    window.removeEventListener('storage', fn);
  };
}

// ---------- Personal pins (on-device only) ----------

export function loadPins(): PersonalPin[] {
  try {
    const raw = localStorage.getItem(PINS_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw) as PersonalPin[];
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(
      p =>
        p &&
        typeof p.id === 'string' &&
        typeof p.name === 'string' &&
        Number.isFinite(p.lat) &&
        Number.isFinite(p.lng)
    );
  } catch {
    return [];
  }
}

function savePins(pins: PersonalPin[]): void {
  try {
    localStorage.setItem(PINS_KEY, JSON.stringify(pins));
  } catch {
    // Storage unavailable — pins simply don't persist this session.
  }
  notifyCompassChanged();
}

export function addPin(name: string, lat: number, lng: number): PersonalPin {
  const pin: PersonalPin = {
    id: `pin-${Date.now()}-${Math.floor(Math.random() * 1e6)}`,
    name,
    lat,
    lng,
    createdAt: Date.now(),
  };
  savePins([...loadPins(), pin]);
  return pin;
}

export function deletePin(id: string): void {
  savePins(loadPins().filter(p => p.id !== id));
  // A deleted pin can no longer be the target. Read the RAW
  // record here, not loadCompassTarget(): that reader already
  // treats a target pointing at a missing pin as no target, so
  // it would report null and the stale record would linger.
  try {
    const raw = localStorage.getItem(TARGET_KEY);
    const t = raw ? (JSON.parse(raw) as CompassTarget) : null;
    if (t && t.kind === 'pin' && t.id === id) clearCompassTarget();
  } catch {
    // Unreadable target record — nothing to clear.
  }
}

// ---------- The compass target ----------

export function loadCompassTarget(): CompassTarget | null {
  try {
    const raw = localStorage.getItem(TARGET_KEY);
    if (!raw) return null;
    const t = JSON.parse(raw) as CompassTarget;
    if (!t || typeof t.label !== 'string') return null;
    if (t.kind === 'wild') return { kind: 'wild', label: t.label };
    if (t.kind === 'venue' || t.kind === 'battle' || t.kind === 'pin') {
      if (!Number.isFinite(t.lat) || !Number.isFinite(t.lng)) return null;
      // A pin target whose pin was deleted is no target at all.
      if (t.kind === 'pin' && !loadPins().some(p => p.id === t.id)) return null;
      return t;
    }
    return null;
  } catch {
    return null;
  }
}

export function setCompassTarget(target: CompassTarget): void {
  try {
    localStorage.setItem(TARGET_KEY, JSON.stringify(target));
  } catch {
    // Best-effort: the compass still holds it for the session via
    // the change event readers re-read on their own state.
  }
  notifyCompassChanged();
}

export function clearCompassTarget(): void {
  try {
    localStorage.removeItem(TARGET_KEY);
  } catch {
    // Nothing to clear.
  }
  notifyCompassChanged();
}

export function venueTarget(venue: DemoVenue): CompassTarget {
  return { kind: 'venue', id: venue.id, label: venue.name, lat: venue.lat, lng: venue.lng };
}

export function pinTarget(pin: PersonalPin): CompassTarget {
  return { kind: 'pin', id: pin.id, label: pin.name, lat: pin.lat, lng: pin.lng };
}

export function wildTarget(name: string): CompassTarget {
  return { kind: 'wild', label: name };
}

// The venue the player last chose with "🧭 Guide me there" — kept
// separately from the active target so the compass picker can list
// the chosen venue even after the player switches to another
// target and wants the venue back.
export function loadChosenVenueId(): string | null {
  try {
    return localStorage.getItem(CHOSEN_VENUE_KEY);
  } catch {
    return null;
  }
}

export function setChosenVenueId(id: string): void {
  try {
    localStorage.setItem(CHOSEN_VENUE_KEY, id);
  } catch {
    // Best-effort.
  }
  notifyCompassChanged();
}

// ---------- Battle spots ----------
// A battle spot for the compass = a demo venue running a Battle
// Night (existing demo buzz data — Valley Ember Lounge today).
export function battleNightVenues(): DemoVenue[] {
  return DEMO_VENUES.filter(v => buzzForVenue(v.id)?.event?.name === 'Battle Night');
}

export function battleTarget(venue: DemoVenue): CompassTarget {
  return {
    kind: 'battle',
    id: venue.id,
    label: `Battle Night — ${venue.name}`,
    lat: venue.lat,
    lng: venue.lng,
  };
}

export function nearestBattleVenue(from: { lat: number; lng: number } | null): DemoVenue | null {
  const venues = battleNightVenues();
  if (venues.length === 0) return null;
  if (!from) return venues[0];
  let best = venues[0];
  let bestD = Number.POSITIVE_INFINITY;
  for (const v of venues) {
    const d = distanceMeters(from, v);
    if (d < bestD) {
      bestD = d;
      best = v;
    }
  }
  return best;
}

// ---------- Geo math (on-device, pure) ----------

const EARTH_R_M = 6_371_000;
const toRad = (deg: number) => (deg * Math.PI) / 180;

export function distanceMeters(
  a: { lat: number; lng: number },
  b: { lat: number; lng: number }
): number {
  const dLat = toRad(b.lat - a.lat);
  const dLng = toRad(b.lng - a.lng);
  const s =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(toRad(a.lat)) * Math.cos(toRad(b.lat)) * Math.sin(dLng / 2) * Math.sin(dLng / 2);
  return 2 * EARTH_R_M * Math.asin(Math.min(1, Math.sqrt(s)));
}

// Initial bearing in compass degrees (0 = north, 90 = east).
export function bearingDeg(
  a: { lat: number; lng: number },
  b: { lat: number; lng: number }
): number {
  const lat1 = toRad(a.lat);
  const lat2 = toRad(b.lat);
  const dLng = toRad(b.lng - a.lng);
  const y = Math.sin(dLng) * Math.cos(lat2);
  const x = Math.cos(lat1) * Math.sin(lat2) - Math.sin(lat1) * Math.cos(lat2) * Math.cos(dLng);
  const deg = (Math.atan2(y, x) * 180) / Math.PI;
  return (deg + 360) % 360;
}

// Wrap a relative bearing to [-180, 180) — the compass arrow's
// rotation: 0 = straight ahead, positive = to the right.
export function wrapDeg(deg: number): number {
  return ((deg + 540) % 360) - 180;
}

export function formatDistance(m: number): string {
  if (!Number.isFinite(m)) return '—';
  if (m < 1000) return `${Math.max(0, Math.round(m))} m`;
  return `${(m / 1000).toFixed(m < 10000 ? 2 : 1)} km`;
}
