// Incoming message producer (Round 22, Eddie 2026-11-18) — the
// one simulated arrival for messages. Headless, like the other
// producers: it writes into the threads store and the
// notifications store; it renders nothing.
//
// Shape (the brief's discipline, mirroring the venue producer's
// trigger discipline):
// - At most ONE seeded arrival per session, and only into a
//   conversation that already exists (a person thread with
//   history — somebody you've actually been talking to texts
//   again). It never creates a thread out of nowhere and never
//   fires for a stranger: the sender is a demo friend with a
//   scripted reply bank, never a blocked person.
// - The line comes from the person's own bank (data/replies.ts
//   PERSON_REPLIES) — the same voice the thread already speaks.
// - It waits for a quiet moment: the player is not in the Inbox
//   (they'd see it arrive live) and no other toast is up (news
//   doesn't pile on news).
// - TYPE-ONLY, by Eddie's law: the notification record is
//   "💬 New message from <name>" + a generic pointer to the
//   Inbox. The line itself is written ONLY to the thread — it
//   never appears in the record, the toast, or the list.
import React, { useEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import { useNotifications } from '../contexts/NotificationsContext';
import { PERSON_REPLIES } from '../data/replies';
import { demoPersonById, loadSocial } from '../utils/social';
import { loadFriends } from '../utils/friends';
import {
  appendMessage,
  ensurePersonThread,
  getThread,
  migrateThreadReadState,
  personThreadId,
} from '../utils/threads';
import { getSpaceModeration, isRemovedParticipant, threadSpaceId } from '../utils/moderation';

const SESSION_KEY = 'glacer-inbox-seeded-arrival';
const FIRST_CHECK_MS = 6000;
const POLL_MS = 4000;
const GIVE_UP_MS = 150000;

const IncomingMessageProducer: React.FC = () => {
  const { notify, toasts } = useNotifications();
  const location = useLocation();
  const firedRef = useRef(false);
  const toastsRef = useRef(toasts);
  toastsRef.current = toasts;
  const pathRef = useRef(location.pathname);
  pathRef.current = location.pathname;

  useEffect(() => {
    migrateThreadReadState();
    let stopped = false;
    let poll: number | null = null;
    const startedAt = Date.now();

    const attempt = () => {
      if (stopped || firedRef.current) return;
      if (Date.now() - startedAt > GIVE_UP_MS) return;
      let alreadySeeded = false;
      try {
        alreadySeeded = sessionStorage.getItem(SESSION_KEY) === '1';
      } catch {
        alreadySeeded = false;
      }
      if (alreadySeeded) {
        firedRef.current = true;
        return;
      }
      // Not while the player is standing in the Inbox, and not on
      // top of another pop-up.
      if (pathRef.current.startsWith('/messages')) return;
      if (toastsRef.current.length > 0) return;

      const blocked = new Set(loadSocial().blocked);
      const candidates = loadFriends()
        .filter(id => !blocked.has(id))
        // Round 35: a person muted (or removed) in their 1:1
        // conversation space never arrives there — mute governs
        // what the space displays, arrivals included.
        .filter(id => {
          const spaceMod = getSpaceModeration(threadSpaceId(personThreadId(id)));
          const key = `person:${id}`;
          return !spaceMod.mutedKeys.includes(key) && !isRemovedParticipant(spaceMod, key);
        })
        .map(id => demoPersonById(id))
        .filter(e => e !== null)
        .filter(e => (PERSON_REPLIES[e.person.id] ?? []).length > 0)
        // A conversation already going reads most natural — prefer
        // friends whose thread exists with history.
        .sort((a, b) => {
          const ta = getThread(personThreadId(a.person.id))?.messages.length ?? 0;
          const tb = getThread(personThreadId(b.person.id))?.messages.length ?? 0;
          return tb - ta;
        });
      const entry = candidates.find(
        e => (getThread(personThreadId(e.person.id))?.messages.length ?? 0) > 0
      );
      if (!entry) return;

      const person = entry.person;
      const threadId = ensurePersonThread(person);
      const thread = getThread(threadId);
      if (!thread) return;
      const lastThem = [...thread.messages].reverse().find(m => m.from === 'them')?.text;
      const bank = PERSON_REPLIES[person.id] ?? [];
      const pool = bank.length > 1 && lastThem ? bank.filter(l => l !== lastThem) : bank;
      if (pool.length === 0) return;
      const text = pool[Math.floor(Math.random() * pool.length)];

      const updated = appendMessage(threadId, { from: 'them', text, ts: Date.now() });
      if (!updated) return;
      firedRef.current = true;
      try {
        sessionStorage.setItem(SESSION_KEY, '1');
      } catch {
        // Private mode: the ref still caps it for this session.
      }
      notify({
        id: `message-${threadId}-${Date.now()}`,
        kind: 'message',
        title: `💬 New message from ${person.name}`,
        body: 'Tap to read it in your Inbox',
        route: `/messages?thread=${threadId}`,
        personId: person.id,
        demo: true,
      });
    };

    const first = window.setTimeout(() => {
      attempt();
      poll = window.setInterval(attempt, POLL_MS);
    }, FIRST_CHECK_MS);
    return () => {
      stopped = true;
      window.clearTimeout(first);
      if (poll !== null) window.clearInterval(poll);
    };
  }, [notify]);

  return null;
};

export default IncomingMessageProducer;
