// Swap-return banner (Round 14, Eddie 2026-11-17): the Navidex
// half of the pre-fight swap. It renders ONLY while a swap-return
// context is pending (utils/swapReturn.ts — stamped by the swap
// buttons on /challenge and Battle Step 1, 30-minute TTL):
//
//   pending pick:  "🔄 Picking your fighter for: {context} —
//                   tap the ✓ on a card to choose."
//   pick landed:   "✓ {name} is your fighter now." + the way back.
//
// "Back to your battle →" clears the context and navigates to the
// pairing (the challenge handoff / Battle plumbing rebuild it —
// the pairing was never stored here). "Stay here" clears the
// context without navigating: wandering off is always allowed,
// the pick still applies app-wide, and nothing traps the player
// in the errand. Renders nothing when no swap is pending, so the
// Navidex looks exactly as before for every other visit.
import React, { useEffect, useState } from 'react';
import { Box, Button, Paper, Typography } from '@mui/material';
import { useNavigate } from 'react-router-dom';
import {
  clearSwapReturn,
  loadSwapReturn,
  SWAP_PICKED_EVENT,
  type SwapReturn,
} from '../utils/swapReturn';

const SwapReturnBanner: React.FC = () => {
  const navigate = useNavigate();
  const [record, setRecord] = useState<SwapReturn | null>(() => loadSwapReturn());

  // A ✓ pick stamps the record and fires SWAP_PICKED_EVENT in
  // this tab; re-read so the banner flips to its picked state the
  // moment the choice lands.
  useEffect(() => {
    const refresh = () => setRecord(loadSwapReturn());
    window.addEventListener(SWAP_PICKED_EVENT, refresh);
    return () => window.removeEventListener(SWAP_PICKED_EVENT, refresh);
  }, []);

  if (!record) return null;

  const back = () => {
    clearSwapReturn();
    navigate(record.returnTo);
  };
  const stay = () => {
    clearSwapReturn();
    setRecord(null);
  };

  return (
    <Paper
      data-testid="swap-return-banner"
      sx={{
        mx: { xs: 2, sm: 3 },
        mt: 2,
        px: 2,
        py: 1.5,
        borderRadius: '16px',
        border: '1px solid #e8912d',
        bgcolor: 'rgba(232, 145, 45, 0.10)',
        display: 'flex',
        alignItems: 'center',
        gap: 1.5,
        flexWrap: 'wrap',
      }}
    >
      <Typography variant="body1" sx={{ fontWeight: 700, flex: '1 1 240px' }}>
        {record.pickedName ? (
          <>✓ {record.pickedName} is your fighter now.</>
        ) : (
          <>🔄 Picking your fighter for: {record.contextLabel} — tap the ✓ on a card to choose.</>
        )}
      </Typography>
      <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
        <Button
          variant={record.pickedName ? 'contained' : 'outlined'}
          size="small"
          onClick={back}
          data-testid="swap-return-back"
          sx={{ fontWeight: 'bold', textTransform: 'none' }}
        >
          Back to your battle →
        </Button>
        <Button
          variant="text"
          size="small"
          onClick={stay}
          data-testid="swap-return-stay"
          sx={{ textTransform: 'none' }}
        >
          Stay in the Navidex
        </Button>
      </Box>
    </Paper>
  );
};

export default SwapReturnBanner;
